import clsx from 'clsx';
import React, {
  ElementType,
  ReactElement,
  ReactNode,
  forwardRef,
  useMemo,
} from 'react';
import { isElement } from 'react-is';

import {
  chipContainerCSS,
  chipValueCSS,
  chipWrapperCSS,
} from './BaseChip.sty.js';
import { ChipPrefix, ChipSuffix } from './ChipContent.js';
import { ChipDeleteButton } from './ChipDeleteButton.js';
import { ChipKey } from './ChipKey.js';
import { ChipContext } from './contexts/ChipContext.js';
import type { ChipProps } from './types/chip.js';
import { _useId } from '../../core/hooks/useId.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { fieldColorsCSS } from '../../styles/field.sty.js';
import { textStyleCSS } from '../../styles/textStyle.sty.js';
import { Text } from '../../typography/Text.js';

//#region Typings
type ChipSlots = {
  deleteButton: ReactNode | null;
  key: ReactNode[];
  value: ReactNode[];
  prefixIcons: ReactNode[];
  suffixIcons: ReactNode[];
};
//#endregion Typings

/** Iterates over child nodes to extract specific component slots. */
const getChipSlots = (node: ReactNode) => {
  const slots: ChipSlots = {
    deleteButton: null,
    prefixIcons: [],
    suffixIcons: [],
    value: [],
    key: [],
  };

  for (const child of React.Children.toArray(node)) {
    if (isElement(child)) {
      switch (child.type) {
        case ChipPrefix:
          slots.prefixIcons.push(child);
          break;
        case ChipSuffix:
          slots.suffixIcons.push(child);
          break;
        case ChipKey:
          slots.key.push(child);
          break;
        case ChipDeleteButton:
          slots.deleteButton = child;
          break;
        default:
          child && slots.value.push(child);
      }
    } else {
      child && slots.value.push(child);
    }
  }

  return slots;
};

/** Chip component */
const BaseChip: <E extends ElementType = 'div'>(
  props: ChipProps<E>,
) => ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends ElementType>(
    props: ChipProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const {
      children,
      as = 'div' as E,
      variant = 'emphasized',
      color = 'neutral',
      size = 'default',
      disabled = false,
      'data-testid': dataTestId,
      maxWidth,
      className: consumerClassName,
      style: consumerStyle,
      ...remainingProps
    }: ChipProps<E> = props;

    const { prefixIcons, suffixIcons, deleteButton, key, value } = useMemo(
      () => getChipSlots(children),
      [children],
    );

    const { focusProps, focusClassName } = useFocusRing({
      variant: color,
    });

    const valueId = _useId({ prefix: 'chip-value' });
    const hasValue = value.length > 0;
    const hasKey = key.length > 0;
    const hasPrefix = prefixIcons.length > 0;
    const hasSuffix = suffixIcons.length > 0;

    return (
      <Flex
        as={'div'}
        ref={forwardedRef}
        data-testid={dataTestId}
        gap={2}
        className={clsx(
          chipWrapperCSS({ disabled }),
          consumerClassName,
          fieldColorsCSS({ variant, color, disabled }),
        )}
        style={{
          maxWidth: maxWidth ?? 250,
          ...(consumerStyle ?? {}),
        }}
      >
        <ChipContext.Provider
          value={{
            disabled: disabled,
            variant,
            color,
            size,
            valueId,
            hasKey,
          }}
        >
          <Text
            data-testid="chip-container"
            as={as satisfies ElementType}
            textStyle="base"
            className={clsx(
              'strato-surface',
              focusClassName,
              (as === 'a' || as === 'button') &&
                textStyleCSS({ textStyle: 'base-emphasized' }),
              chipContainerCSS({
                size,
                disabled,
                color,
                variant,
                hasDeleteButton: deleteButton !== null,
              }),
            )}
            {..._mergeProps(
              focusProps,
              remainingProps as Record<string, unknown>,
            )}
          >
            {hasPrefix &&
              prefixIcons.map((node: ReactNode, index: number) => (
                <React.Fragment key={`prefix-node-${index}`}>
                  {node}
                </React.Fragment>
              ))}
            {hasKey &&
              key.map((node: ReactNode, index: number) => (
                <React.Fragment key={`key-node-${index}`}>
                  {node}
                </React.Fragment>
              ))}
            {hasKey && hasValue && <span>:</span>}
            {hasValue &&
              value.map((node, index) => (
                <Flex
                  data-testid="chip-value"
                  key={`value-node-${index}`}
                  id={valueId}
                  className={chipValueCSS}
                >
                  {node}
                </Flex>
              ))}
            {hasSuffix &&
              suffixIcons.map((node, index) => (
                <React.Fragment key={`suffix-node-${index}`}>
                  {node}
                </React.Fragment>
              ))}
          </Text>
          {deleteButton}
        </ChipContext.Provider>
      </Flex>
    );
  },
);

/**
 * Use the `Chip` component to present a piece of information in a compact form.
 * @internal
 */
export const _BaseChip = Object.assign(BaseChip, {
  Prefix: ChipPrefix,
  Suffix: ChipSuffix,
  Key: ChipKey,
  DeleteButton: ChipDeleteButton,
});

(_BaseChip as typeof _BaseChip & { displayName: string }).displayName =
  'BaseChip';
